{
  "decisions": [
    {
      "requirement_id": "KMU-001",
      "methods": [
        "Test"
      ],
      "rationale": "Sistemin e-Devlet entegrasyonu ile oturum açma işlevinin çalışıp çalışmadığı, gerçek bir kullanıcı girişi yapılarak gözlemlenerek doğrulanabilir."
    },
    {
      "requirement_id": "KMU-002",
      "methods": [
        "Test"
      ],
      "rationale": "15 dakikalık bekleme süresinin sonunda oturumun sonlandırılması ve yönlendirme davranışı, zamanlayıcı testleri ile sistemin çalıştırılarak doğrulanabilir."
    },
    {
      "requirement_id": "KMU-003",
      "methods": [
        "Test"
      ],
      "rationale": "Art arda 5 başarısız giriş denemesi sonrası hesap kilitlenmesi ve 30 dakikalık süre, sisteme girdi verilerek ve sonuç gözlemlenerek test edilebilir."
    },
    {
      "requirement_id": "KMU-004",
      "methods": [
        "Test"
      ],
      "rationale": "Dosya türü, boyut limiti (10 MB) ve adet limiti (5 dosya) kurallarının uygulanıp uygulanmadığı, farklı senaryolarla sisteme dosya yüklenerek test edilebilir."
    },
    {
      "requirement_id": "KMU-005",
      "methods": [
        "Test"
      ],
      "rationale": "Başvuru tamamlanınca benzersiz numara üretimi ve e-posta gönderimi, sistemin çalıştırılması ve çıktıların gözlemlenmesiyle doğrulanabilir."
    },
    {
      "requirement_id": "KMU-006",
      "methods": [
        "Test"
      ],
      "rationale": "Taslak kaydetme ve 30 gün içinde kaldığı yerden devam etme işlevi, sisteme veri girilip bekletildikten sonra erişim denemesiyle test edilebilir."
    },
    {
      "requirement_id": "KMU-007",
      "methods": [
        "İnceleme"
      ],
      "rationale": "WCAG 2.1 AA uyumluluğu, kullanıcı arayüzünün kod yapısı, HTML etiketleri ve erişilebilirlik özelliklerinin gözle denetlenerek (inceleme) doğrulanır."
    },
    {
      "requirement_id": "KMU-008",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Verilerin yalnızca Türkiye sınırları içindeki sunucularda saklanması, altyapı yapılandırma belgeleri ve sunucu konumlarının gözle denetlenerek (inceleme) doğrulanır."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "SW-001",
      "methods": [
        "Test"
      ],
      "rationale": "Gereksinim, belirli bir girdi (geçersiz belirteç) verildiğinde sistemin gözlemlenebilir davranışını (HTTP 401 yanıtı) tanımladığı için test ile doğrulanmalıdır."
    },
    {
      "requirement_id": "SW-002",
      "methods": [
        "Test"
      ],
      "rationale": "Rol tabanlı erişim kontrolünün ve yetkisiz isteklerde HTTP 403 yanıtının, farklı rollerle yapılan istekler üzerinden sistemin çalıştırılarak gözlemlenmesiyle doğrulanması gerekir."
    },
    {
      "requirement_id": "SW-003",
      "methods": [
        "Test"
      ],
      "rationale": "Hız sınırlama eşiğinin aşılması durumunda HTTP 429 yanıtı ve Retry-After başlığının, kontrollü istek yükü uygulanarak sistemin davranışının gözlemlenmesiyle test edilebilir."
    },
    {
      "requirement_id": "SW-004",
      "methods": [
        "Analiz"
      ],
      "rationale": "Belirli bir yük altında (2.000 istek/sn) 99. persentil gecikme metriklerinin karşılaştırılması, performans testlerinin sonuçlarının istatistiksel analizi veya modellemesi gerektirdiğinden analiz yöntemi uygundur."
    },
    {
      "requirement_id": "SW-005",
      "methods": [
        "Test"
      ],
      "rationale": "Arka uç gecikmesinin 5 saniyeyi aşması durumunda isteğin sonlandırılması ve HTTP 504 yanıtının, simüle edilmiş gecikme senaryolarıyla sistemin çalıştırılarak gözlemlenmesiyle test edilebilir."
    },
    {
      "requirement_id": "SW-006",
      "methods": [
        "Test"
      ],
      "rationale": "Yapılandırma değişikliğinin yeniden başlatma gerektirmeden ve devam eden istekleri düşürmeden uygulanması, canlı sistem üzerinde değişiklik yapılarak ve istek akışının kesintisiz devam etmesi gözlemlenerek test edilmelidir."
    },
    {
      "requirement_id": "SW-007",
      "methods": [
        "Test"
      ],
      "rationale": "İsteklerin loglanmasının doğrulanması için istekler gönderilip log çıktısının kontrol edilmesi gerekir; ancak log içeriğinin yapılandırılmış formata uygunluğunun ve tüm alanların varlığının sistematik olarak denetlenmesi için inceleme de gereklidir."
    },
    {
      "requirement_id": "SW-008",
      "methods": [
        "Analiz"
      ],
      "rationale": "Aylık kullanılabilirlik yüzdesinin (99.95%) hesaplanması, uzun süreli izleme verilerinin veya sistem güvenilirlik modelinin istatistiksel analizi gerektirdiğinden analiz yöntemi seçilir."
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-001",
      "title": "Macro-averaged F1 score validation on held-out set",
      "covers": [
        "AI-002"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The classification model is trained and ready for evaluation. The held-out evaluation dataset is available and contains labeled documents across all classes.",
      "test_inputs": "Held-out evaluation dataset with ground truth labels.",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Run the classification model on the held-out evaluation dataset.",
          "expected": "The model generates predictions for all documents in the dataset."
        },
        {
          "no": 2,
          "action": "Calculate the macro-averaged F1 score by comparing predictions with ground truth labels.",
          "expected": "The calculated macro-averaged F1 score is at least 0.90."
        }
      ]
    },
    {
      "id": "TC-002",
      "title": "Recall parity between Turkish and English documents",
      "covers": [
        "AI-008"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The classification model is trained and ready for evaluation. The held-out evaluation dataset contains a sufficient number of labeled documents in both Turkish and English.",
      "test_inputs": "Held-out evaluation dataset containing Turkish and English documents with ground truth labels.",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Run the classification model on the held-out evaluation dataset.",
          "expected": "The model generates predictions for all documents."
        },
        {
          "no": 2,
          "action": "Calculate the recall score for documents written in Turkish.",
          "expected": "A recall value for the Turkish subset is obtained."
        },
        {
          "no": 3,
          "action": "Calculate the recall score for documents written in English.",
          "expected": "A recall value for the English subset is obtained."
        },
        {
          "no": 4,
          "action": "Calculate the absolute difference between the Turkish recall and the English recall.",
          "expected": "The absolute difference is less than or equal to 5 percentage points."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-01",
      "title": "Casualty data encryption verification",
      "covers": [
        "MED-006"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The application is installed and configured on the tablet. A test casualty record is available for creation.",
      "test_inputs": "Sample casualty data (e.g., Name: 'Test Patient', ID: '12345').",
      "assumptions": "Access to the device's file system or storage inspection tools is available to verify the encryption algorithm used.",
      "steps": [
        {
          "no": 1,
          "action": "Create a new casualty record with the test input data in the application.",
          "expected": "The casualty record is successfully saved and appears in the list of casualties."
        },
        {
          "no": 2,
          "action": "Inspect the storage location of the casualty data on the device using file system tools or a hex editor.",
          "expected": "The data is not stored in plain text and is encrypted."
        },
        {
          "no": 3,
          "action": "Verify the encryption algorithm used for the stored casualty data via system logs, configuration files, or cryptographic inspection tools.",
          "expected": "The encryption algorithm is confirmed to be AES-256."
        }
      ]
    },
    {
      "id": "TC-02",
      "title": "Battery life under defined usage profile",
      "covers": [
        "MED-008"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The tablet is fully charged (100% battery). The 'defined usage profile' is documented and available (e.g., continuous screen on, specific brightness, periodic data entry).",
      "test_inputs": "Defined usage profile script or manual procedure.",
      "assumptions": "The 'defined usage profile' is a standardized sequence of operations (e.g., 50% brightness, continuous app usage, no background sync) that can be executed consistently.",
      "steps": [
        {
          "no": 1,
          "action": "Start the tablet with 100% battery and begin executing the defined usage profile continuously.",
          "expected": "The application is running and the battery level starts to decrease."
        },
        {
          "no": 2,
          "action": "Monitor the battery level and application status for 8 hours while maintaining the defined usage profile.",
          "expected": "The application remains operational and the battery level is above 0% after 8 hours."
        },
        {
          "no": 3,
          "action": "Record the battery percentage at the 8-hour mark.",
          "expected": "The battery percentage is greater than 0%, confirming the tablet operated for at least 8 hours."
        }
      ]
    }
  ]
}

